-- Cyprus milestone translations (ES/DE/FR) — replaces the
-- English-placeholder draft stub generated by new_country_scaffold.py.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-b2g-central-2019', 'es', 'Los organismos públicos centrales deben recibir facturas electrónicas EN 16931', 'La Ley 89(I)/2019 transpone la Directiva 2014/55/UE de la UE: todos los organismos públicos centrales deben poder recibir y procesar facturas electrónicas conformes con la norma europea EN 16931. La emisión por parte de los proveedores sigue siendo voluntaria — se trata de una obligación de recepción solo para los organismos gubernamentales.', '["Los proveedores de organismos centrales del gobierno chipriota pueden emitir facturas electrónicas estructuradas voluntariamente a través de Peppol o el portal del gobierno, aunque no existe obligación de hacerlo"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-b2g-central-2019', 'de', 'Zentrale öffentliche Stellen müssen EN-16931-E-Rechnungen empfangen können', 'Das Gesetz 89(I)/2019 setzt die EU-Richtlinie 2014/55/EU um: Alle zentralen öffentlichen Stellen müssen elektronische Rechnungen empfangen und verarbeiten können, die der europäischen Norm EN 16931 entsprechen. Die Ausstellung durch Lieferanten bleibt freiwillig — dies ist eine reine Empfangspflicht für staatliche Stellen.', '["Lieferanten zentraler zypriotischer Regierungsstellen können strukturierte E-Rechnungen freiwillig über Peppol oder das Regierungsportal ausstellen, obwohl hierzu keine Pflicht besteht"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-b2g-central-2019', 'fr', 'Les organismes publics centraux doivent pouvoir recevoir des factures électroniques EN 16931', 'La loi 89(I)/2019 transpose la directive européenne 2014/55/UE : tous les organismes publics centraux doivent pouvoir recevoir et traiter des factures électroniques conformes à la norme européenne EN 16931. L''émission par les fournisseurs reste volontaire — il s''agit uniquement d''une obligation de réception pour les organismes gouvernementaux.', '["Les fournisseurs des organismes centraux du gouvernement chypriote peuvent émettre des factures électroniques structurées volontairement via Peppol ou le portail gouvernemental, bien qu''il n''y ait aucune obligation de le faire"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-b2g-subcentral-2020', 'es', 'Los organismos públicos subcentrales también deben recibir facturas electrónicas', 'La obligación de recepción se amplía a todos los organismos públicos restantes — las autoridades regionales y locales, además de las entidades del gobierno central ya cubiertas desde 2019 — completando el despliegue de la Directiva 2014/55/UE en Chipre. La emisión sigue siendo voluntaria en todo momento; un objetivo del 1 de enero de 2022 para hacer obligatoria la emisión fue discutido por el Ministerio de Hacienda pero nunca se promulgó, y un objetivo similar de 2024 también se pospuso.', '["Compruebe si el organismo público concreto al que factura es una entidad central o subcentral — ambas están ahora obligadas a aceptar facturas electrónicas conformes, aunque ninguna le obliga a enviarlas"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-b2g-subcentral-2020', 'de', 'Auch nachgeordnete öffentliche Stellen müssen E-Rechnungen empfangen können', 'Die Empfangspflicht wird auf alle übrigen öffentlichen Stellen ausgeweitet — regionale und lokale Behörden, zusätzlich zu den bereits seit 2019 erfassten zentralen Regierungsstellen — womit Zyperns Umsetzung der Richtlinie 2014/55/EU abgeschlossen wird. Die Ausstellung bleibt durchgehend freiwillig; ein für den 1. Januar 2022 diskutiertes Ziel des Finanzministeriums, die Ausstellung verpflichtend zu machen, wurde nie umgesetzt, und ein ähnliches Ziel für 2024 wurde ebenfalls verschoben.', '["Prüfen Sie, ob die konkrete öffentliche Stelle, an die Sie fakturieren, eine zentrale oder nachgeordnete Einrichtung ist — beide müssen mittlerweile konforme E-Rechnungen akzeptieren, wobei keine von beiden Sie zur Ausstellung verpflichtet"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-b2g-subcentral-2020', 'fr', 'Les organismes publics infra-centraux doivent également recevoir des factures électroniques', 'L''obligation de réception s''étend à tous les organismes publics restants — autorités régionales et locales, en plus des organismes du gouvernement central déjà couverts depuis 2019 — achevant le déploiement de la directive 2014/55/UE à Chypre. L''émission reste volontaire tout au long ; un objectif du 1er janvier 2022 visant à rendre l''émission obligatoire a été discuté par le ministère des Finances mais jamais promulgué, et un objectif similaire pour 2024 a également été reporté.', '["Vérifiez si l''organisme public spécifique auquel vous facturez est une entité centrale ou infra-centrale — les deux sont désormais tenues d''accepter des factures électroniques conformes, bien qu''aucune ne vous oblige à en envoyer"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-vida-2030', 'es', 'Entra en vigor el reporte digital B2B transfronterizo de ViDA', 'Independientemente de si Chipre llega a promulgar su propio mandato nacional de emisión B2B o B2G, la directiva del IVA en la Era Digital (ViDA) de la UE exige capacidad de facturación electrónica estructurada y reporte digital para las transacciones B2B intracomunitarias a partir del 1 de julio de 2030 — derecho de la UE confirmado (Directiva (UE) 2025/516 del Consejo).', '["Las empresas que comercien de forma transfronteriza dentro de la UE deberían prepararse para tener capacidad de facturación electrónica y reporte conforme a EN 16931 para esta fecha, con independencia de cualquier mandato chipriota nacional"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-vida-2030', 'de', 'Die grenzüberschreitende B2B-Digitalmeldung nach ViDA tritt in Kraft', 'Unabhängig davon, ob Zypern jemals eine eigene inländische B2B- oder B2G-Ausstellungspflicht erlässt, verlangt die EU-Richtlinie VAT in the Digital Age (ViDA) ab dem 1. Juli 2030 strukturierte E-Rechnungs- und digitale Meldefähigkeit für innergemeinschaftliche B2B-Umsätze — bestätigtes EU-Recht (Richtlinie (EU) 2025/516 des Rates).', '["Unternehmen mit grenzüberschreitendem Handel innerhalb der EU sollten bis zu diesem Datum EN-16931-konforme E-Rechnungs- und Meldefähigkeit einplanen, unabhängig von einer etwaigen zypriotischen inländischen Pflicht"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-vida-2030', 'fr', 'La déclaration numérique B2B transfrontalière ViDA entre en vigueur', 'Que Chypre finisse ou non par promulguer sa propre obligation nationale d''émission B2B ou B2G, la directive européenne TVA à l''ère numérique (ViDA) exige une capacité de facturation électronique structurée et de déclaration numérique pour les transactions B2B intracommunautaires à partir du 1er juillet 2030 — droit de l''UE confirmé (directive (UE) 2025/516 du Conseil).', '["Les entreprises réalisant du commerce transfrontalier au sein de l''UE devraient se préparer à disposer d''une capacité de facturation électronique et de déclaration conforme à l''EN 16931 d''ici cette date, indépendamment de toute obligation nationale chypriote"]');
